    'type'            => 'in',
    'timestamp'       => now(),
    'latitude'        => $latitude,
    'longitude'       => $longitude,
    'within_geofence' => $withinGeofence,
    'notes'           => $notes,
]);

return response()->json([
    'success'             => true,
    'record'              => $record->load('employee'),
    'within_geofence'     => $withinGeofence,
