    fail:    'text-red-700',
    idle:    'text-neutral-500',
  }
  return (
    <view className={`p-3 rounded-xl border ${bgStyles[result.status]}`}>
      <text className={`text-xs ${textStyles[result.status]}`}>{result.text}</text>
    </view>
  )
}

